-- HU-04: solo prueba aislada; sin UPDATE, DELETE, DDL ni usuarios.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
DO $$ BEGIN
 IF current_database() <> 'esart_hu03_pruebas' THEN
   RAISE EXCEPTION 'Destino no autorizado: solo esart_hu03_pruebas';
 END IF;
 IF (SELECT rolsuper FROM pg_roles WHERE rolname=current_user) THEN
   RAISE EXCEPTION 'No se permite superusuario';
 END IF;
 IF (SELECT version_num FROM public.alembic_version) IS DISTINCT FROM '0001' THEN
   RAISE EXCEPTION 'Se requiere HU-03 revision 0001';
 END IF;
END $$;
LOCK TABLE public.permisos IN SHARE ROW EXCLUSIVE MODE;
DO $seed$
DECLARE r jsonb; nuevo uuid; padre uuid; insertados int := 0; omitidos int := 0;
BEGIN
 FOR r IN SELECT value FROM jsonb_array_elements('[{"codigo": "gestionar_sistemas", "descripcion": "Crear, editar y dar de baja sistemas de artilleria."}, {"codigo": "ver_sistemas", "descripcion": "Consultar la ficha tecnica de cada sistema."}, {"codigo": "estado_ubicacion", "descripcion": "Ver el estado operacional y la posicion geografica de cada sistema en el mapa."}, {"codigo": "gestionar_operadores", "descripcion": "Asignar y cambiar los soldados operadores de cada sistema de artilleria."}, {"codigo": "graficar_blancos", "descripcion": "Graficar blancos, rangos efectivos de fuego y zonas de impacto sobre el mapa."}, {"codigo": "graficar_rutas", "descripcion": "Dibujar y consultar rutas de desplazamiento de sistemas de artilleria."}, {"codigo": "graficar_plan_operacion", "descripcion": "Dibujar planes de operacion sobre el mapa con sistemas asignados."}, {"codigo": "calculos_balisticos", "descripcion": "Ejecutar calculos de tiro: elevacion, deriva, carga y correcciones."}, {"codigo": "configurar_tablas_balisticas", "descripcion": "Gestionar tablas balisticas y parametros de municion por tipo de sistema."}, {"codigo": "misiones_fuego", "descripcion": "Crear, ejecutar y consultar misiones de fuego de artilleria."}, {"codigo": "aprobar_mision", "descripcion": "Aprobar o rechazar ordenes de fuego (nivel comando)."}, {"codigo": "cancelar_mision", "descripcion": "Cancelar una mision de fuego que ya se encuentra en ejecucion."}, {"codigo": "gestionar_municion", "descripcion": "Registrar consumo, altas y bajas de municion. Gestionar stock."}, {"codigo": "ver_municion", "descripcion": "Consultar existencias de municion y alertas de minimos."}, {"codigo": "gestionar_inventario", "descripcion": "Administrar repuestos, insumos y partes de los sistemas."}, {"codigo": "ver_inventario", "descripcion": "Consultar el inventario de repuestos e insumos."}, {"codigo": "ver_mantenimiento", "descripcion": "Consultar historial de mantenimientos realizados y proximas fechas programadas."}, {"codigo": "registrar_mantenimiento", "descripcion": "Cargar la ejecucion de un mantenimiento: fecha, tipo y nivel realizado."}, {"codigo": "programar_mantenimiento", "descripcion": "Agendar fechas de proximos mantenimientos preventivos."}, {"codigo": "infografia_sistema", "descripcion": "Ver la tarjeta completa del sistema al hacer clic en el mapa: comandante, operadores, municion, disparos, mantenimiento y certificaciones."}, {"codigo": "ver_infografia_personal", "descripcion": "Ver unicamente la seccion de personal y certificaciones en la infografia del sistema."}, {"codigo": "historial_sistemas", "descripcion": "Consultar historial de movimientos, mantenimientos y disparos realizados."}, {"codigo": "exportar_historial", "descripcion": "Descargar el historial de sistemas en formato Excel o PDF."}, {"codigo": "gestionar_unidades", "descripcion": "Registrar nuevas unidades militares en el sistema (batallones, baterias, etc.). Util para agregar unidades a las que se asignan sistemas de artilleria."}, {"codigo": "modulo_esart", "descripcion": "Acceso total al modulo de la Escuela de Artilleria: cursos, instructores, alumnos, malla curricular y reentrenamientos."}, {"codigo": "ver_personal_esart", "descripcion": "Consultar personal y certificaciones de la ESART sin poder modificar."}, {"codigo": "gestionar_doctrina", "descripcion": "Subir, editar y desactivar documentos PDF de doctrina artillera (balistica, protocolos, manuales ejercito, doctrina ejercito, manuales sistemas)."}, {"codigo": "ver_doctrina", "descripcion": "Consultar y descargar los documentos PDF de doctrina artillera disponibles."}, {"codigo": "reportes_enviar_ver", "descripcion": "Acceso completo al modulo de reportes: enviar, recibir y consultar informes."}, {"codigo": "reportes_solo_enviar", "descripcion": "Enviar informes unicamente, sin acceso a los recibidos."}, {"codigo": "reportes_solo_ver", "descripcion": "Consultar informes recibidos sin poder enviar."}, {"codigo": "reportes_exportar", "descripcion": "Generar y descargar reportes en PDF o Excel."}, {"codigo": "ver_auditoria", "descripcion": "Consultar el log de actividad: quien hizo que accion y cuando."}, {"codigo": "ver_dashboard", "descripcion": "Acceder al panel general con indicadores del teatro de operaciones."}, {"codigo": "configurar_alertas", "descripcion": "Definir umbrales de alerta: dias sin mantenimiento, stock minimo, disparos acumulados."}, {"codigo": "recibir_alertas", "descripcion": "Recibir notificaciones automaticas cuando se superen los umbrales configurados."}]'::jsonb) LOOP
  INSERT INTO public.permisos (codigo,descripcion) VALUES (r->>'codigo',r->>'descripcion')
  ON CONFLICT (codigo) DO NOTHING RETURNING id INTO nuevo;
  IF nuevo IS NULL THEN omitidos := omitidos + 1; ELSE insertados := insertados + 1; END IF;
 END LOOP;
 RAISE NOTICE '%', json_build_object('tabla','permisos','insertados',insertados,'omitidos',omitidos,'errores',0);
END $seed$;
COMMIT;
